using Microsoft.AspNetCore.Components;
using Microsoft.JSInterop;

namespace sv_26fb9b246deb42e1af61644bb2b9866c.Components;

public partial class InfiniteScrollList<TItem> : ComponentBase, IAsyncDisposable
{
    [Inject] private IJSRuntime JS { get; set; } = default!;

    /// <summary>The collection of items to display.</summary>
    [Parameter, EditorRequired] public IReadOnlyList<TItem> Items { get; set; } = [];

    /// <summary>Template for rendering each item.</summary>
    [Parameter, EditorRequired] public RenderFragment<TItem> ChildContent { get; set; } = default!;

    /// <summary>Whether more items are available to load.</summary>
    [Parameter] public bool HasMore { get; set; }

    /// <summary>Callback invoked when the sentinel element becomes visible.</summary>
    [Parameter, EditorRequired] public EventCallback OnLoadMore { get; set; }

    private ElementReference _sentinel;
    private IJSObjectReference? _module;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? _selfRef;
    private bool _isLoading;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/infinite-scroll.js");
            _selfRef = DotNetObjectReference.Create(this);
            await _module.InvokeVoidAsync("observe", _sentinel, _selfRef);
        }
    }

    [JSInvokable]
    public async Task OnIntersecting()
    {
        if (_isLoading || !HasMore)
            return;

        _isLoading = true;
        await OnLoadMore.InvokeAsync();
        _isLoading = false;
        StateHasChanged();

        // Re-observe after the list updates so the sentinel is tracked again
        if (HasMore && _module is not null)
        {
            await _module.InvokeVoidAsync("observe", _sentinel, _selfRef);
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            try
            {
                await _module.InvokeVoidAsync("disconnect");
                await _module.DisposeAsync();
            }
            catch (JSDisconnectedException)
            {
                // Circuit already gone — safe to ignore.
            }
        }

        _selfRef?.Dispose();
    }
}

let observer = null;

export function observe(sentinel, dotNetRef) {
    disconnect();

    observer = new IntersectionObserver(entries => {
        const entry = entries[0];
        if (entry?.isIntersecting) {
            observer.disconnect();
            dotNetRef.invokeMethodAsync("OnIntersecting");
        }
    }, { rootMargin: "200px" });

    observer.observe(sentinel);
}

export function disconnect() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
}

